  // 2. Update merchant profile info (Protected)
  app.put('/api/admin/merchants/:category/:id', requireAdminAuth, async (req, res) => {
    try {
      const { category, id } = req.params;
      const updates = req.body || {};

      if (!serverSupabase) {
        return res.json({ success: true, message: 'আপডেট সফলভাবে সম্পন্ন হয়েছে (লোকাল মোড)' });
      }

      let tableName = 'product_sellers';
      let payload: any = {};

      if (category === 'seller') {
        tableName = 'product_sellers';
        payload = {
          name: updates.name,
          owner_name: updates.name,
          phone: updates.phone,
          whatsapp: updates.whatsapp,
          district: updates.district,
          upazila: updates.upazila,
          shop_name: updates.shopName,
          address: updates.address,
          status: updates.status
        };
      } else if (category === 'provider') {
        tableName = 'service_providers';
        payload = {
          profile_name: updates.name,
          phone_number: updates.phone,
          district: updates.district,
          upazila: updates.upazila,
          services_selected: updates.profession,
          blood_group: updates.bloodGroup,
          status: updates.status
        };
      } else if (category === 'member') {
        tableName = 'permanent_members';
        payload = {
          full_name: updates.name,
          phone_number: updates.phone,
          district: updates.district,
          upazila: updates.upazila,
          profession: updates.profession,
          blood_group: updates.bloodGroup,
          status: updates.status
        };
      } else if (category === 'blood') {
        tableName = 'blood_donors';
        payload = {
          full_name: updates.name,
          phone_number: updates.phone,
          whatsapp_number: updates.whatsapp,
          district: updates.district,
          upazila: updates.upazila,
          blood_group: updates.bloodGroup
        };
      }

      const { error } = await serverSupabase.from(tableName).update(payload).eq('id', id);
      if (error) {
        console.warn(`[AdminMerchants] Update error in ${tableName}:`, error.message);
      }

      return res.json({ success: true, message: 'প্রোফাইল তথ্য সফলভাবে আপডেট হয়েছে।' });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: err?.message });
    }
  });

  // 3. Verify merchant account (Protected)
  app.post('/api/admin/merchants/:category/:id/verify', requireAdminAuth, async (req, res) => {
    try {
      const { category, id } = req.params;

      if (!serverSupabase) {
        return res.json({ success: true, message: 'অ্যাকাউন্ট ভেরিফিকেশন সফল হয়েছে।' });
      }

      let tableName = 'product_sellers';
      if (category === 'provider') tableName = 'service_providers';
      else if (category === 'member') tableName = 'permanent_members';
      else if (category === 'blood') tableName = 'blood_donors';

      const { error } = await serverSupabase.from(tableName).update({
        status: 'verified',
        is_verified: true,
        is_approved: true
      }).eq('id', id);

      if (error) {
        console.warn(`[AdminMerchants] Verify error in ${tableName}:`, error.message);
      }

      return res.json({ success: true, message: 'অ্যাকাউন্টটি সফলভাবে ভেরিফাই করা হয়েছে।' });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: err?.message });
    }
  });

  // 4. Change or reset merchant password (Super-Admin / Admin Protected with Bcrypt Hashing)
  app.post('/api/admin/merchants/:category/:id/reset-password', strictLimiter('admin-merchant-reset-pw', 10, 15 * 60 * 1000), requireAdminAuth, async (req, res) => {
    try {
      const { category, id } = req.params;
      const { newPassword } = req.body || {};

      if (!newPassword || String(newPassword).trim().length < 8) {
        return res.status(400).json({ success: false, message: 'পাসওয়ার্ড ন্যূনতম ৮ অক্ষরের হতে হবে।' });
      }

      const cleanPass = String(newPassword).trim();
      const hashedPassword = bcrypt.hashSync(cleanPass, 10);

      if (serverSupabase) {
        let tableName = 'product_sellers';
        if (category === 'provider') tableName = 'service_providers';
        else if (category === 'member') tableName = 'permanent_members';
        else if (category === 'blood') tableName = 'blood_donors';

        const { error } = await serverSupabase.from(tableName).update({
          password: hashedPassword,
          pass_word: hashedPassword
        }).eq('id', id);

        if (error) {
          console.warn(`[AdminMerchants] Password update error in ${tableName}:`, error.message);
        }
      }

      return res.json({ success: true, message: 'পাসওয়ার্ড সফলভাবে এনক্রিপ্ট করে পরিবর্তন করা হয়েছে।' });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: err?.message });
    }
  });

  // 4b. Change or reset customer password (Admin Protected with Bcrypt Hashing)
  app.post('/api/admin/customers/:id/reset-password', strictLimiter('admin-customer-reset-pw', 10, 15 * 60 * 1000), requireAdminAuth, async (req, res) => {
    try {
      const { id } = req.params;
      const { phone, newPassword } = req.body || {};

      if (!newPassword || String(newPassword).trim().length < 8) {
        return res.status(400).json({ success: false, message: 'পাসওয়ার্ড ন্যূনতম ৮ অক্ষরের হতে হবে।' });
      }

      const cleanPass = String(newPassword).trim();
      const hashedPassword = bcrypt.hashSync(cleanPass, 10);
      const cleanPhone = String(phone || '').trim().replace(/[^0-9]/g, '');

      if (serverSupabase) {
        try {
          if (cleanPhone) {
            await serverSupabase.from('profiles').update({
              password: hashedPassword,
              pass_word: hashedPassword,
              updated_at: new Date().toISOString()
            }).or(`phone.eq.${cleanPhone},phone_number.eq.${cleanPhone}`);
          }
          await serverSupabase.from('profiles').update({
            password: hashedPassword,
            pass_word: hashedPassword,
            updated_at: new Date().toISOString()
          }).eq('id', id);
        } catch (dbErr: any) {
          console.warn('[AdminCustomerPassword] Supabase update warning:', dbErr?.message);
        }
      }

      return res.json({ success: true, message: 'কাস্টমার পাসওয়ার্ড সফলভাবে ডাটাবেজে আপডেট করা হয়েছে।' });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: err?.message });
    }
  });

