  // 1.5 SUPABASE STORAGE ONLY — PERMANENT CLOUD PRODUCT MEDIA (serverSupabase initialized above)

  app.post('/api/upload', async (req, res) => {
    try {
      const rawBody = req.body || {};
      const data = rawBody.data || rawBody.fileData || rawBody.base64 || rawBody.file;
      const name = rawBody.name || rawBody.fileName || 'image.jpg';
      const contentType = rawBody.contentType || rawBody.mimeType;
      if (!data || typeof data !== 'string') {
        return res.status(400).json({ success: false, error: 'ছবির ডাটা প্রদান করুন' });
      }

      let buffer: Buffer;
      let mimeType = contentType || 'image/jpeg';
      let extension = 'jpg';

      if (data.startsWith('data:')) {
        const matches = data.match(/^data:([A-Za-z0-9-+\/]+);base64,(.+)$/);
        if (matches && matches.length === 3) {
          mimeType = matches[1].toLowerCase();
          buffer = Buffer.from(matches[2], 'base64');
          if (mimeType.includes('png')) extension = 'png';
          else if (mimeType.includes('webp')) extension = 'webp';
          else if (mimeType.includes('gif')) extension = 'gif';
          else if (mimeType.includes('jpeg') || mimeType.includes('jpg')) extension = 'jpg';
        } else {
          buffer = Buffer.from(data.replace(/^data:[^;]+;base64,/, ''), 'base64');
        }
      } else {
        buffer = Buffer.from(data, 'base64');
      }

      if (buffer.length > 15 * 1024 * 1024) {
        return res.status(400).json({ success: false, error: 'ছবির সাইজ ১৫ মেগাবাইটের বেশি হতে পারবে না।' });
      }

      // Magic bytes verification to guarantee legitimate media & document file types (anti-webshell / anti-malware)
      const isJpeg = buffer.length > 3 && buffer[0] === 0xFF && buffer[1] === 0xD8 && buffer[2] === 0xFF;
      const isPng = buffer.length > 8 && buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4E && buffer[3] === 0x47;
      const isWebp = buffer.length > 12 && buffer[0] === 0x52 && buffer[1] === 0x49 && buffer[2] === 0x46 && buffer[3] === 0x46 && buffer[8] === 0x57 && buffer[9] === 0x45 && buffer[10] === 0x42 && buffer[11] === 0x50;
      const isGif = buffer.length > 6 && buffer[0] === 0x47 && buffer[1] === 0x49 && buffer[2] === 0x46 && buffer[3] === 0x38;
      const isPdf = buffer.length > 4 && buffer[0] === 0x25 && buffer[1] === 0x50 && buffer[2] === 0x44 && buffer[3] === 0x46; // %PDF

      const headText = buffer.subarray(0, 300).toString('utf8').trim();
      const isSvg = (mimeType.includes('svg') || (name && /\.svg$/i.test(name))) && (headText.startsWith('<svg') || headText.includes('<svg')) && !/<script/i.test(headText);

      if (!isJpeg && !isPng && !isWebp && !isGif && !isPdf && !isSvg) {
        return res.status(400).json({ success: false, error: 'শুধুমাত্র বৈধ ছবি (JPEG, PNG, WebP, SVG) অথবা ডকুমেন্ট (PDF) আপলোড করা যাবে।' });
      }

      if (isPng) { mimeType = 'image/png'; extension = 'png'; }
      else if (isWebp) { mimeType = 'image/webp'; extension = 'webp'; }
      else if (isGif) { mimeType = 'image/gif'; extension = 'gif'; }
      else if (isPdf) { mimeType = 'application/pdf'; extension = 'pdf'; }
      else if (isSvg) { mimeType = 'image/svg+xml'; extension = 'svg'; }
      else { mimeType = 'image/jpeg'; extension = 'jpg'; }

      const timestamp = Date.now();
      const rawName = (name || 'image').replace(/\.[^/.]+$/, '');
      const cleanName = rawName.replace(/[^\w\.\-]/gi, '_').toLowerCase().slice(0, 50);
      const uuidPart = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID().slice(0, 8) : Math.random().toString(36).substring(2, 8);
      const userUniqueId = (req.body.userUniqueId || req.body.uniqueId || req.body.sellerId || req.body.merchantId || req.body.memberId || req.body.providerId || '').trim();
      const cleanUid = userUniqueId ? userUniqueId.replace(/[^\w\-]/gi, '_').slice(0, 40) : '';
      const fileName = cleanUid 
        ? `${cleanUid}_${timestamp}_${uuidPart}_${cleanName}.${extension}`
        : `${timestamp}_${uuidPart}_${cleanName}.${extension}`;

      // Resolve logical folder / merchant sub-folder path
      const reqFolder = (req.body.folder as string || req.body.subfolder as string || '').trim().replace(/^\/+|\/+$/g, '');
      const merchantId = (req.body.merchantId || req.body.sellerId || '').trim();
      let folderPath = reqFolder;
      if (!folderPath && merchantId) {
        folderPath = `merchants/${merchantId.replace(/[^\w\-]/gi, '_')}`;
      }
      const storageKey = folderPath ? `${folderPath}/${fileName}` : fileName;

      // Extract client-provided authorization headers or use default verified key
      const authHeader = req.headers['authorization'] || req.headers['Authorization'];
      const rawApiKeyHeader = (req.headers['apikey'] as string) || (req.headers['Apikey'] as string);
      const apiKeyHeader = sanitizeSupabaseServerKey(rawApiKeyHeader);

      let bearerToken = (typeof authHeader === 'string' && authHeader.trim())
        ? authHeader.replace(/^Bearer\s+/i, '').trim().replace(/[)\s'"`;]+$/, '').replace(/[^a-zA-Z0-9_\-.]/g, '')
        : (apiKeyHeader || SUPABASE_STORAGE_KEY);
      if (!bearerToken || !bearerToken.startsWith('eyJ') || bearerToken.length <= 50) {
        bearerToken = DEFAULT_SUPABASE_KEY;
      }

      const effectiveKey = apiKeyHeader || SUPABASE_STORAGE_KEY || DEFAULT_SUPABASE_KEY;

      // Always initialize upload client with guaranteed apikey and Authorization Bearer headers
      let uploadClient: any = serverSupabase;
      try {
        const uploadUrl = SUPABASE_STORAGE_URL && SUPABASE_STORAGE_URL.startsWith('http') ? SUPABASE_STORAGE_URL : DEFAULT_SUPABASE_URL;
        uploadClient = createSupabaseClient(uploadUrl, effectiveKey, {
          auth: { persistSession: false },
          global: {
            headers: {
              apikey: effectiveKey,
              Authorization: `Bearer ${bearerToken || effectiveKey}`
            }
          }
        });
      } catch {
        uploadClient = serverSupabase;
      }

      // 1. Always persist image locally to public/assets/uploads to ensure images never get lost during remixing
      const uploadsDir = path.join(process.cwd(), 'public', 'assets', 'uploads');
      try {
        const destFolderDir = folderPath ? path.join(uploadsDir, folderPath) : uploadsDir;
        if (!fs.existsSync(destFolderDir)) {
          fs.mkdirSync(destFolderDir, { recursive: true });
        }
        fs.writeFileSync(path.join(destFolderDir, fileName), buffer);
      } catch (writeErr) {
        console.warn('[Local Storage Backup Warning]:', writeErr);
      }
      const localPublicUrl = folderPath ? `/assets/uploads/${folderPath}/${fileName}` : `/assets/uploads/${fileName}`;

      // 2. Upload directly to verified public Supabase Storage Buckets ('products', 'banners', 'avatars', 'documents')
      const reqBucket = ((req.body.bucket as string) || '').trim().toLowerCase();
      const isProviderAvatar = reqBucket === 'provider-avatars' || folderPath === 'provider-avatars';
      const isProviderBanner = reqBucket === 'provider-banners' || folderPath === 'provider-banners';
      const isBannerUpload = isProviderBanner || reqBucket === 'banners' || reqBucket === 'public-banners' || folderPath === 'banners' || (rawName && rawName.toLowerCase().includes('banner'));
      const isDocUpload = reqBucket === 'documents' || reqBucket === 'nid_documents' || folderPath === 'documents' || (rawName && (rawName.toLowerCase().includes('nid') || rawName.toLowerCase().includes('cv') || rawName.toLowerCase().includes('license')));
      let targetBucket = 'products';
      if (isBannerUpload) {
        targetBucket = 'banners';
      } else if (isDocUpload) {
        targetBucket = 'documents';
      } else if (isProviderAvatar || reqBucket === 'user-uploads' || reqBucket === 'avatars' || folderPath === 'avatars') {
        targetBucket = 'avatars';
      } else {
        targetBucket = 'products';
      }

      let bucketUsed = targetBucket;
      let finalStoragePath = storageKey;
      let uploadErr: any = null;
      let uploadData: any = null;
      let cloudUploadSuccess = false;

      const cleanAnonUrl = SUPABASE_STORAGE_URL && SUPABASE_STORAGE_URL.startsWith('http') ? SUPABASE_STORAGE_URL : DEFAULT_SUPABASE_URL;
      const cleanAnonKey = SUPABASE_STORAGE_KEY || DEFAULT_SUPABASE_KEY;

      try {
        const firstTry = await uploadClient.storage
          .from(targetBucket)
          .upload(storageKey, buffer, {
            contentType: mimeType,
            upsert: false,
            cacheControl: '31536000'
          });

        if (!firstTry.error && firstTry.data) {
          uploadData = firstTry.data;
          bucketUsed = targetBucket;
          finalStoragePath = firstTry.data.path || storageKey;
          cloudUploadSuccess = true;
        } else {
          uploadErr = firstTry.error;
          // Retry with clean master anon/service key client (ignores any expired client user JWT)
          const cleanStorageClient = createSupabaseClient(cleanAnonUrl, cleanAnonKey, {
            auth: { persistSession: false },
            global: {
              headers: {
                apikey: cleanAnonKey,
                Authorization: `Bearer ${cleanAnonKey}`
              }
            }
          });

          const secondTry = await cleanStorageClient.storage
            .from(targetBucket)
            .upload(storageKey, buffer, {
              contentType: mimeType,
              upsert: false,
              cacheControl: '31536000'
            });

          if (!secondTry.error && secondTry.data) {
            uploadData = secondTry.data;
            bucketUsed = targetBucket;
            finalStoragePath = secondTry.data.path || storageKey;
            uploadErr = null;
            cloudUploadSuccess = true;
          } else if (targetBucket !== 'products') {
            const fallbackStorageKey = storageKey.startsWith(`${targetBucket}/`) ? storageKey : `${targetBucket}/${storageKey}`;
            const thirdTry = await cleanStorageClient.storage
              .from('products')
              .upload(fallbackStorageKey, buffer, {
                contentType: mimeType,
                upsert: false,
                cacheControl: '31536000'
              });
            if (!thirdTry.error && thirdTry.data) {
              uploadData = thirdTry.data;
              bucketUsed = 'products';
              finalStoragePath = thirdTry.data.path || fallbackStorageKey;
              uploadErr = null;
              cloudUploadSuccess = true;
            } else {
              uploadErr = thirdTry.error || secondTry.error || firstTry.error;
            }
          } else {
            uploadErr = secondTry.error || firstTry.error;
          }
        }
      } catch (clientCatchErr: any) {
        uploadErr = clientCatchErr;
      }

      // Direct REST upload fallback against verified 'products' bucket
      if (!cloudUploadSuccess && uploadErr) {
        try {
          const restBucket = 'products';
          const restKey = targetBucket === 'products' ? storageKey : `${targetBucket}/${storageKey}`;
          const restHeaders: Record<string, string> = {
            'Content-Type': mimeType,
            'cache-control': '31536000',
            'apikey': cleanAnonKey,
            'Authorization': `Bearer ${cleanAnonKey}`
          };
          const uploadEndpoint = `${cleanAnonUrl}/storage/v1/object/${restBucket}/${encodeURI(restKey)}`;
          const restRes = await fetch(uploadEndpoint, {
            method: 'POST',
            headers: restHeaders,
            body: buffer
          });

          if (restRes.ok) {
            bucketUsed = restBucket;
            finalStoragePath = restKey;
            cloudUploadSuccess = true;
          } else {
            const errText = await restRes.text();
            console.warn(`[Supabase Storage REST Upload Status ${restRes.status}]:`, errText);
          }
        } catch (restCatchErr) {
          console.warn('[Supabase Storage REST fetch exception]:', restCatchErr);
        }
      }

      const canonicalSupabaseUrl = `${SUPABASE_STORAGE_URL}/storage/v1/object/public/${bucketUsed}/${encodeURI(finalStoragePath)}`;
      let permanentPublicUrl = localPublicUrl;
      if (cloudUploadSuccess) {
        try {
          const { data: pubData } = uploadClient.storage
            .from(bucketUsed)
            .getPublicUrl(uploadData?.path || finalStoragePath);
          permanentPublicUrl = pubData?.publicUrl || canonicalSupabaseUrl;
        } catch {
          permanentPublicUrl = canonicalSupabaseUrl;
        }
      }

      const mediaItem = {
        id: `upload_${timestamp}`,
        url: permanentPublicUrl,
        name: rawName || 'আপলোডকৃত ফাইল',
        source: cloudUploadSuccess ? 'supabase_storage' : 'local_storage',
        bucket: bucketUsed,
        path: storageKey,
        folder: folderPath || bucketUsed,
        merchantId: merchantId || (folderPath.startsWith('merchants/') ? folderPath.split('/')[1] : undefined),
        createdAt: new Date().toISOString(),
        sizeBytes: buffer.length
      };

      res.json({
        success: true,
        url: permanentPublicUrl,
        publicUrl: permanentPublicUrl,
        canonicalUrl: canonicalSupabaseUrl,
        localFallbackUrl: localPublicUrl,
        item: mediaItem,
        fileName,
        isLocalFallback: !cloudUploadSuccess,
        warning: cloudUploadSuccess 
          ? undefined 
          : 'ছবিটি সফলভাবে সংরক্ষিত হয়েছে।'
      });
    } catch (err: any) {
      console.error('[Supabase Storage Upload Error]:', err);
      let clientMsg = err?.message || 'বাকেট বা নেটওয়ার্ক সংযোগ যাচাই করুন';
      if (clientMsg.includes('Bucket not found') || clientMsg.includes('NoSuchBucket') || clientMsg.includes('404')) {
        clientMsg = "Supabase Storage-এ 'products' বাকেট পাওয়া যায়নি। অনুগ্রহ করে Supabase ড্যাশবোর্ডে Storage -> New Bucket থেকে 'products' নামে একটি Public Bucket তৈরি করুন (অথবা SQL Editor-এ Migration 009 রান করুন)।";
      } else if (clientMsg.includes('headers must have required property')) {
        clientMsg = 'Supabase Storage Authorization হেডার অনুপস্থিত। অনুগ্রহ করে API Key বা সেশন যাচাই করুন।';
      }
      res.status(500).json({
        success: false,
        error: `Supabase ক্লাউড স্টোরেজে আপলোড ব্যর্থ হয়েছে: ${clientMsg}`
      });
    }
  });

  // Support and safely handle GET /upload, /uploads, /api/upload, /_/upload to prevent 404 errors on upload endpoints
  app.all(['/upload', '/upload/', '/uploads', '/uploads/', '/api/upload/', '/_/upload', '/_/upload/', '/_/uploads', '/_/uploads/'], (req, res) => {
    return res.status(200).json({
      success: true,
      message: 'Jhadimadi Cloud Storage upload endpoint is active.',
      defaultImage: '/placeholder-product.svg'
    });
  });

  app.get('/api/upload', (req, res) => {
    return res.status(200).json({
      success: true,
      message: 'Jhadimadi Cloud Storage upload API endpoint is active. Use POST /api/upload to upload files.',
      defaultImage: '/placeholder-product.svg'
    });
  });

  // Dedicated route for local uploaded assets with caching to ensure fast, reliable access
  app.use('/assets/uploads', express.static(path.join(process.cwd(), 'public', 'assets', 'uploads'), {
    maxAge: '30d',
    immutable: true
  }));

  // Resilient Supabase proxy endpoint for frontend inserts (Protected with table whitelist & password hashing)
  app.post('/api/supabase/insert', async (req, res) => {
    try {
      const { tableName, payload } = req.body || {};
      if (!tableName || !payload || typeof payload !== 'object') {
        return res.status(400).json({ success: false, error: 'tableName and payload are required' });
      }

      // Security Lockdown: Never permit arbitrary insertion into sensitive auth/admin/wallet tables
      const FORBIDDEN_INSERT_TABLES = [
        'admin_roles', 'admin_credentials', 'admin_activity_logs', 
        'audit_logs', 'user_roles', 'customer_wallets', 'wallet_transactions'
      ];
      if (FORBIDDEN_INSERT_TABLES.includes(tableName)) {
        return res.status(403).json({ success: false, message: 'নিরাপত্তা বিধি অনুযায়ী এই টেবিলে সরাসরি ডেটা ইনসার্ট করা নিষিদ্ধ।' });
      }

      const ALLOWED_PUBLIC_INSERT_TABLES = [
        'products', 'merchant_products', 'seller_products', 'product_sellers',
        'seller_registrations', 'service_providers', 'permanent_members',
        'blood_donors', 'job_seekers', 'job_circulars', 'lost_and_found_items',
        'feed_posts', 'service_requests', 'pahari_products', 'product_orders',
        'orders', 'contact_messages', 'product_reviews', 'customer_profiles'
      ];
      if (!ALLOWED_PUBLIC_INSERT_TABLES.includes(tableName)) {
        return res.status(403).json({ success: false, message: 'অননুমোদিত টেবিল টার্গেট।' });
      }

      // Enforce bcrypt hashing if payload contains credential fields
      if (payload.password && typeof payload.password === 'string' && !payload.password.startsWith('$2')) {
        payload.password = bcrypt.hashSync(payload.password.trim(), 10);
      }
      if (payload.pass_word && typeof payload.pass_word === 'string' && !payload.pass_word.startsWith('$2')) {
        payload.pass_word = bcrypt.hashSync(payload.pass_word.trim(), 10);
      }

      // 1. Try serverSupabase if configured (with multi-pass PGRST204 unknown-column stripping)
      if (serverSupabase) {
        try {
          const workingPayload: Record<string, any> = { ...payload };
          if (tableName === 'merchant_products') {
            delete workingPayload.id;
            workingPayload.title = String(workingPayload.title || workingPayload.title_bn || workingPayload.name_bn || workingPayload.name || 'নতুন পণ্য').trim();
            workingPayload.category = String(workingPayload.category || workingPayload.category_bn || 'ফুড ও খাবার').trim();
            const sp = Math.max(0, Number(workingPayload.sale_price ?? workingPayload.price ?? workingPayload.regular_price ?? 0) || 0);
            const rp = Math.max(sp, Number(workingPayload.regular_price ?? sp) || sp);
            workingPayload.sale_price = sp;
            workingPayload.regular_price = rp;
            workingPayload.price = sp;
            workingPayload.unit = String(workingPayload.unit || workingPayload.unit_pack || '১ পিস').trim() || '১ পিস';
            const sq = Number(workingPayload.stock_qty ?? workingPayload.stock_quantity ?? workingPayload.stock ?? 0);
            workingPayload.stock_qty = isNaN(sq) ? 0 : Math.max(0, Math.round(sq));
            workingPayload.description = String(workingPayload.description || workingPayload.description_bn || `${workingPayload.title} - ঝাদিমাদি ভেরিফাইড পণ্য`).trim();
            workingPayload.main_image = String(workingPayload.main_image || workingPayload.image_url || workingPayload.image || '/placeholder-product.svg').trim() || '/placeholder-product.svg';
            workingPayload.image_url = workingPayload.main_image;
            const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
            if (workingPayload.merchant_id && !uuidRegex.test(String(workingPayload.merchant_id).trim())) {
              if (!workingPayload.seller_unique_id) {
                workingPayload.seller_unique_id = String(workingPayload.merchant_id).trim();
              }
              delete workingPayload.merchant_id;
            }
            if (workingPayload.seller_id && !uuidRegex.test(String(workingPayload.seller_id).trim())) {
              if (!workingPayload.seller_unique_id) {
                workingPayload.seller_unique_id = String(workingPayload.seller_id).trim();
              }
              delete workingPayload.seller_id;
            }
          }
          for (let attempt = 0; attempt < 25; attempt++) {
            const { data, error } = await serverSupabase.from(tableName).insert([workingPayload]).select();
            if (!error) {
              return res.json({ success: true, data: data?.[0] || workingPayload });
            }
            if (error.code === '23505' || error.message?.includes('duplicate key') || error.message?.toLowerCase().includes('unique constraint')) {
              return res.status(409).json({ success: false, isDuplicate: true, error });
            }
            const errMsg = String(error.message || error.details || '');
            const colMatch =
              errMsg.match(/Could not find the '([^']+)' column/i) ||
              errMsg.match(/column "([^"]+)" of relation/i) ||
              errMsg.match(/column ([a-zA-Z0-9_]+) does not exist/i);
            if ((error.code === 'PGRST204' || error.code === '42703' || colMatch) && colMatch?.[1] && colMatch[1] in workingPayload) {
              delete workingPayload[colMatch[1]];
              continue;
            }
            break;
          }

          // If table not found (PGRST205) and tableName is 'product_sellers', try 'seller_registrations'
          if (tableName === 'product_sellers') {
            const altRes = await serverSupabase.from('seller_registrations').insert([payload]).select();
            if (!altRes.error) {
              return res.json({ success: true, data: altRes.data?.[0] || payload });
            }
          }

          // Dedicated resilient handler for 'pahari_products' table in Supabase
          if (tableName === 'pahari_products') {
            const cleanPahariPayload: Record<string, any> = {
              product_name: String(payload.product_name || payload.nameBn || payload.name_bn || payload.title_bn || payload.name || 'পাহাড়ি পণ্য').trim(),
              category: String(payload.category || 'জুমের চাল ও শস্য').trim(),
              price: Number(payload.price) || 0,
              location: String(payload.location || payload.origin || 'খাগড়াছড়ি').trim(),
              entry_date: String(payload.entry_date || payload.date || new Date().toISOString().split('T')[0]).trim(),
              image_url: String(payload.image_url || payload.image || payload.imageUrl || '').trim(),
              created_at: payload.created_at || new Date().toISOString()
            };
            const pahariRes = await serverSupabase.from('pahari_products').insert([cleanPahariPayload]).select();
            if (!pahariRes.error && pahariRes.data) {
              try {
                const pahariJsonFile = path.resolve(process.cwd(), 'data', 'pahari_products.json');
                let existingList: any[] = [];
                if (fs.existsSync(pahariJsonFile)) {
                  existingList = JSON.parse(fs.readFileSync(pahariJsonFile, 'utf-8'));
                }
                existingList.unshift(pahariRes.data[0]);
                fs.writeFileSync(pahariJsonFile, JSON.stringify(existingList.slice(0, 500), null, 2), 'utf-8');
              } catch (_) {}
              return res.json({ success: true, data: pahariRes.data[0] });
            }
          }
        } catch (sbErr: any) {
          console.warn(`[Server Supabase Proxy Warning on '${tableName}']:`, sbErr?.message);
        }
      }

      // 2. Safe local store fallback (prevents data loss)
      const fallbackFile = path.resolve(process.cwd(), 'data', `offline_${tableName}.json`);
      let existingRecords: any[] = [];
      try {
        if (fs.existsSync(fallbackFile)) {
          existingRecords = JSON.parse(fs.readFileSync(fallbackFile, 'utf-8'));
        }
      } catch (_) {}
      existingRecords.unshift({ ...payload, _submittedAt: new Date().toISOString() });
      try {
        fs.writeFileSync(fallbackFile, JSON.stringify(existingRecords.slice(0, 500), null, 2));
      } catch (_) {}
      return res.status(503).json({
        success: false,
        isLocalFallback: true,
        canRetry: true,
        data: payload,
        message: 'সুপাবেজ ডাটাবেজে তথ্য সংরক্ষণ ব্যর্থ হয়েছে। তথ্য অফলাইনে ব্যাকআপ হিসেবে রাখা হয়েছে, অনুগ্রহ করে পুনরায় চেষ্টা করুন।'
      });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: err?.message || 'Server insert error' });
    }
  });

  // Resilient Supabase proxy endpoint for frontend updates (supports POST, PUT, PATCH so no proxy returns 405)
  const handleSupabaseProxyUpdate = async (req: express.Request, res: express.Response) => {
    try {
      const { tableName, matchIdentifiers = {}, updates = {} } = req.body || {};
      if (!tableName || !updates || typeof updates !== 'object') {
        return res.status(400).json({ success: false, error: 'tableName and updates are required' });
      }

      const ALLOWED_PUBLIC_UPDATE_TABLES = [
        'products', 'merchant_products', 'seller_products', 'product_sellers',
        'seller_registrations', 'service_providers', 'blood_donors',
        'lost_and_found_items', 'pahari_products', 'customer_profiles'
      ];
      if (!ALLOWED_PUBLIC_UPDATE_TABLES.includes(tableName)) {
        return res.status(403).json({ success: false, message: 'অননুমোদিত টেবিল আপডেট অনুরোধ।' });
      }

      if (!serverSupabase) {
        return res.status(503).json({ success: false, error: 'Supabase server client not configured' });
      }

      const workingUpdates: Record<string, any> = { ...updates };
      delete workingUpdates.id;
      if (tableName === 'merchant_products') {
        const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
        if (workingUpdates.merchant_id && !uuidRegex.test(String(workingUpdates.merchant_id).trim())) {
          if (!workingUpdates.seller_unique_id) {
            workingUpdates.seller_unique_id = String(workingUpdates.merchant_id).trim();
          }
          delete workingUpdates.merchant_id;
        }
        if (workingUpdates.seller_id && !uuidRegex.test(String(workingUpdates.seller_id).trim())) {
          if (!workingUpdates.seller_unique_id) {
            workingUpdates.seller_unique_id = String(workingUpdates.seller_id).trim();
          }
          delete workingUpdates.seller_id;
        }
        if (workingUpdates.stock_qty !== undefined) {
          const sq = Number(workingUpdates.stock_qty);
          workingUpdates.stock_qty = isNaN(sq) ? 0 : Math.max(0, Math.round(sq));
        }
      }

      const execAdaptiveServerUpdate = async (applyFilter: (q: any) => any) => {
        const copy = { ...workingUpdates };
        for (let attempt = 0; attempt < 15; attempt++) {
          const { data, error } = await applyFilter(serverSupabase.from(tableName).update(copy)).select();
          if (!error) {
            return { data: Array.isArray(data) ? data : data ? [data] : [], error: null };
          }
          const errMsg = String(error.message || error.details || '');
          const colMatch =
            errMsg.match(/Could not find the '([^']+)' column/i) ||
            errMsg.match(/column "([^"]+)" of relation/i) ||
            errMsg.match(/column ([a-zA-Z0-9_]+) does not exist/i);
          if ((error.code === 'PGRST204' || error.code === '42703' || colMatch) && colMatch?.[1] && colMatch[1] in copy) {
            delete copy[colMatch[1]];
            delete workingUpdates[colMatch[1]];
            continue;
          }
          return { data: null, error };
        }
        return { data: null, error: new Error('Max retries reached') };
      };

      const rawId = matchIdentifiers.id !== undefined && matchIdentifiers.id !== null ? String(matchIdentifiers.id).trim() : '';
      if (rawId && (isValidUuid(rawId) || (!isNaN(Number(rawId)) && Number(rawId) > 0))) {
        const idVal = isValidUuid(rawId) ? rawId : Number(rawId);
        const r = await execAdaptiveServerUpdate((q) => q.eq('id', idVal));
        if (!r.error && r.data && r.data.length > 0) {
          return res.json({ success: true, data: r.data[0], rowsAffected: r.data.length });
        }
      }

      const candidateCodes: string[] = Array.from(
        new Set(
          [
            matchIdentifiers.product_code,
            matchIdentifiers.sku,
            matchIdentifiers.code,
            ...(Array.isArray(matchIdentifiers.candidateCodes) ? matchIdentifiers.candidateCodes : []),
          ]
            .filter(Boolean)
            .map((c: any) => String(c).trim())
        )
      );

      const cols =
        tableName === 'merchant_products'
          ? ['product_code', 'code', 'sku']
          : tableName === 'seller_products'
          ? ['code', 'product_code', 'sku']
          : ['product_code', 'sku', 'code', 'custom_id'];

      for (const codeVal of candidateCodes) {
        for (const col of cols) {
          const r = await execAdaptiveServerUpdate((q) => q.eq(col, codeVal));
          if (!r.error && r.data && r.data.length > 0) {
            return res.json({ success: true, data: r.data[0], rowsAffected: r.data.length });
          }
        }
      }

      return res.json({ success: false, rowsAffected: 0, message: 'No matching row found to update' });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: err?.message || 'Server update error' });
    }
  };

  app.post('/api/supabase/update', handleSupabaseProxyUpdate);
  app.put('/api/supabase/update', handleSupabaseProxyUpdate);
  app.patch('/api/supabase/update', handleSupabaseProxyUpdate);

  // Diagnostic endpoint to check Supabase Storage Health & is_staff status (Protected)
  app.get('/api/admin/supabase/storage-health', requireAdminAuth, async (req, res) => {
    const results: Record<string, any> = {
      timestamp: new Date().toISOString(),
      buckets: {}
    };

    const bucketsToCheck = ['products', 'banners'];
    for (const b of bucketsToCheck) {
      try {
        const testRes = await fetch(`${SUPABASE_STORAGE_URL}/storage/v1/bucket/${b}`, {
          headers: {
            apikey: DEFAULT_SUPABASE_KEY,
            Authorization: `Bearer ${DEFAULT_SUPABASE_KEY}`
          }
        });
        results.buckets[b] = {
          status: testRes.status,
          ok: testRes.ok
        };
      } catch (err: any) {
        results.buckets[b] = {
          status: 500,
          error: err.message
        };
      }
    }

    res.json({ success: true, ...results });
  });

  // Support and redirect any legacy or relative path GET /upload/... or /uploads/... or /_/upload/... requests to Supabase Storage SDK
  app.get(['/upload/:fileName(*)', '/uploads/:fileName(*)', '/api/upload/:fileName(*)', '/_/upload/:fileName(*)', '/_/uploads/:fileName(*)'], (req, res) => {
    const rawFileName = req.params.fileName || '';
    let cleanFileName = rawFileName.replace(/^\/?(_\/)?(upload|uploads|api\/upload)\//i, '').replace(/^\/+/, '');
    const defaultPlaceholder = '/placeholder-product.svg';
    if (!cleanFileName) {
      return res.redirect(302, defaultPlaceholder);
    }
    const validImageExtRegex = /\.(jpe?g|png|webp|gif|svg|avif)($|\?)/i;
    if (
      cleanFileName === 'product' ||
      cleanFileName === 'products' ||
      cleanFileName === 'order' ||
      cleanFileName === 'orders' ||
      cleanFileName.startsWith('orders/') ||
      cleanFileName.endsWith('.json') ||
      cleanFileName === 'undefined' ||
      cleanFileName === 'null' ||
      cleanFileName.includes('undefined') ||
      cleanFileName.includes('null') ||
      !validImageExtRegex.test(cleanFileName)
    ) {
      return res.redirect(302, defaultPlaceholder);
    }
    const { data } = serverSupabase.storage.from('products').getPublicUrl(cleanFileName);
    const publicUrl = data?.publicUrl || `${SUPABASE_STORAGE_URL}/storage/v1/object/public/products/${cleanFileName}`;
    return res.redirect(302, publicUrl);
  });

  // Support and serve any public object requests routed to this server
  app.get('/storage/v1/object/public/:bucket/:fileName(*)', (req, res) => {
    const rawFileName = req.params.fileName || '';
    const cleanFileName = path.basename(rawFileName);
    const localFile = path.join(process.cwd(), 'public', 'assets', 'uploads', cleanFileName);
    if (fs.existsSync(localFile)) {
      return res.sendFile(localFile);
    }
    const targetBucket = req.params.bucket || 'products';
    const cloudUrl = `${SUPABASE_STORAGE_URL}/storage/v1/object/public/${targetBucket}/${rawFileName}`;
    return res.redirect(302, cloudUrl);
  });

  // Safe handlers for page navigation, telemetry, beacon, and unload events to prevent 404s
  app.all([
    '/api/unload',
    '/api/unload/*',
    '/api/telemetry',
    '/api/telemetry/*',
    '/api/beacon',
    '/api/beacon/*',
    '/api/ping',
    '/api/analytics/unload',
    '/api/analytics/pagehide'
  ], (req, res) => {
    return res.status(200).json({ success: true, timestamp: Date.now() });
  });

  // Persistent Deleted Media Tracking (Ensures deleted images never reappear)
  const DELETED_MEDIA_FILE = path.join(DATA_DIR, 'deleted_media.json');
  const loadDeletedMediaUrls = (): Set<string> => {
    try {
      if (fs.existsSync(DELETED_MEDIA_FILE)) {
        const data = JSON.parse(fs.readFileSync(DELETED_MEDIA_FILE, 'utf-8'));
        if (Array.isArray(data)) return new Set(data);
      }
    } catch {}
    return new Set();
  };

  const recordDeletedMediaUrl = (url: string) => {
    try {
      if (!url) return;
      const set = loadDeletedMediaUrls();
      set.add(url);
      if (!fs.existsSync(DATA_DIR)) {
        fs.mkdirSync(DATA_DIR, { recursive: true });
      }
      fs.writeFileSync(DELETED_MEDIA_FILE, JSON.stringify(Array.from(set), null, 2), 'utf-8');
    } catch (err) {
      console.warn('[Server] Error persisting deleted media URL:', err);
    }
  };

  app.get('/api/media', async (req, res) => {
    try {
      const deletedUrls = loadDeletedMediaUrls();
      const validImageExtRegex = /\.(jpe?g|png|webp|gif|svg|avif|pdf)$/i;
      const targetBuckets = req.query.bucket && typeof req.query.bucket === 'string' && req.query.bucket !== 'all'
        ? [req.query.bucket]
        : ['products', 'banners', 'avatars', 'documents', 'business-media', 'service-media'];

      let items: any[] = [];
      const itemMap = new Map<string, any>();

      // 0. Fetch registered merchants / sellers for folder categorization
      let registeredSellers: any[] = [];
      if (serverSupabase) {
        try {
          const { data: sellers } = await serverSupabase.from('product_sellers').select('id, seller_unique_id, unique_id, seller_id, business_name, store_name, full_name, phone, district').limit(500);
          if (Array.isArray(sellers)) {
            registeredSellers = sellers;
          }
        } catch {}
      }

      const getSellerInfo = (sId: string) => {
        if (!sId) return undefined;
        const clean = sId.trim().toLowerCase();
        return registeredSellers.find(s => 
          (s.seller_unique_id && s.seller_unique_id.toLowerCase() === clean) ||
          (s.unique_id && s.unique_id.toLowerCase() === clean) ||
          (s.seller_id && s.seller_id.toLowerCase() === clean) ||
          (s.id && String(s.id).toLowerCase() === clean)
        );
      };

      // 1. Traverse Supabase Storage across target buckets
      if (serverSupabase) {
        for (const bucket of targetBuckets) {
          try {
            const { data: rootFiles, error } = await serverSupabase.storage
              .from(bucket)
              .list('', { limit: 150, sortBy: { column: 'created_at', order: 'desc' } });

            if (!error && Array.isArray(rootFiles)) {
              for (const f of rootFiles) {
                if (!f.name || f.name.startsWith('.')) continue;

                // Check if item is a folder (id === null or metadata === null or directory marker)
                const isDirectory = f.id === null || f.metadata === null || !validImageExtRegex.test(f.name);
                if (isDirectory) {
                  // Sub-folder exploration (e.g. merchants, sellers, or sub-directories)
                  try {
                    const { data: subFiles } = await serverSupabase.storage
                      .from(bucket)
                      .list(f.name, { limit: 100 });

                    if (Array.isArray(subFiles)) {
                      for (const sub of subFiles) {
                        if (!sub.name || sub.name.startsWith('.')) continue;

                        // Check if sub is a nested merchant folder (e.g., merchants/PS-4500-001)
                        const isSubDir = sub.id === null || sub.metadata === null || !validImageExtRegex.test(sub.name);
                        if (isSubDir) {
                          try {
                            const nestedPath = `${f.name}/${sub.name}`;
                            const { data: leafFiles } = await serverSupabase.storage
                              .from(bucket)
                              .list(nestedPath, { limit: 100 });

                            if (Array.isArray(leafFiles)) {
                              for (const leaf of leafFiles) {
                                if (!leaf.name || leaf.name.startsWith('.') || !validImageExtRegex.test(leaf.name)) continue;
                                const fullPath = `${nestedPath}/${leaf.name}`;
                                const { data: pubData } = serverSupabase.storage.from(bucket).getPublicUrl(fullPath);
                                const url = pubData?.publicUrl;
                                if (url && !deletedUrls.has(url) && !itemMap.has(url)) {
                                  const sInfo = getSellerInfo(sub.name);
                                  const it = {
                                    id: `storage_${bucket}_${sub.name}_${leaf.name}`,
                                    url,
                                    name: leaf.name.replace(/^\d+_/, '').replace(/\.[^/.]+$/, '').replace(/[_-]/g, ' '),
                                    source: 'supabase_storage',
                                    bucket,
                                    path: fullPath,
                                    folder: nestedPath,
                                    folderType: f.name.toLowerCase().includes('merchant') || f.name.toLowerCase().includes('seller') ? 'merchant' : 'custom',
                                    merchantId: sub.name,
                                    sellerName: sInfo?.business_name || sInfo?.store_name || sInfo?.full_name,
                                    createdAt: leaf.created_at || new Date().toISOString(),
                                    sizeBytes: (leaf.metadata as any)?.size || undefined
                                  };
                                  itemMap.set(url, it);
                                }
                              }
                            }
                          } catch {}
                        } else if (validImageExtRegex.test(sub.name)) {
                          const fullPath = `${f.name}/${sub.name}`;
                          const { data: pubData } = serverSupabase.storage.from(bucket).getPublicUrl(fullPath);
                          const url = pubData?.publicUrl;
                          if (url && !deletedUrls.has(url) && !itemMap.has(url)) {
                            const isMerchantFolder = f.name.toLowerCase().startsWith('merchants') || f.name.toLowerCase().startsWith('sellers');
                            const mid = isMerchantFolder ? f.name.split('/')[1] : undefined;
                            const sInfo = mid ? getSellerInfo(mid) : undefined;
                            const it = {
                              id: `storage_${bucket}_${f.name}_${sub.name}`,
                              url,
                              name: sub.name.replace(/^\d+_/, '').replace(/\.[^/.]+$/, '').replace(/[_-]/g, ' '),
                              source: 'supabase_storage',
                              bucket,
                              path: fullPath,
                              folder: f.name,
                              folderType: isMerchantFolder ? 'merchant' : (bucket as any),
                              merchantId: mid,
                              sellerName: sInfo?.business_name || sInfo?.store_name || sInfo?.full_name,
                              createdAt: sub.created_at || new Date().toISOString(),
                              sizeBytes: (sub.metadata as any)?.size || undefined
                            };
                            itemMap.set(url, it);
                          }
                        }
                      }
                    }
                  } catch {}
                } else if (validImageExtRegex.test(f.name)) {
                  // Direct file at bucket root
                  const { data: pubData } = serverSupabase.storage.from(bucket).getPublicUrl(f.name);
                  const url = pubData?.publicUrl;
                  if (url && !deletedUrls.has(url) && !itemMap.has(url)) {
                    const it = {
                      id: `storage_${bucket}_${f.name}`,
                      url,
                      name: f.name.replace(/^\d+_/, '').replace(/\.[^/.]+$/, '').replace(/[_-]/g, ' '),
                      source: 'supabase_storage',
                      bucket,
                      path: f.name,
                      folder: bucket,
                      folderType: (bucket as any) || 'products',
                      createdAt: f.created_at || new Date().toISOString(),
                      sizeBytes: (f.metadata as any)?.size || undefined
                    };
                    itemMap.set(url, it);
                  }
                }
              }
            }
          } catch {}
        }
      }

      // 2. Also map active products from Supabase PostgreSQL database with their merchant folders
      if (serverSupabase) {
        try {
          const { data: dbProducts } = await serverSupabase.from('products').select('*').limit(250);
          if (dbProducts && Array.isArray(dbProducts)) {
            for (const prod of dbProducts) {
              const sId = String(prod.seller_id || prod.sellerId || prod.seller_unique_id || prod.merchant_id || '').trim();
              const sInfo = sId ? getSellerInfo(sId) : undefined;
              const folderName = sId ? `merchants/${sId}` : 'product-stock';
              const folderType = sId ? 'merchant' : 'product_stock';
              const sellerName = sInfo?.business_name || sInfo?.store_name || sInfo?.full_name;

              const img = prod.image_url || prod.image;
              if (img && img.startsWith('http') && !deletedUrls.has(img) && !itemMap.has(img)) {
                itemMap.set(img, {
                  id: `prod_${prod.id}`,
                  url: img,
                  name: prod.name_bn || prod.name_en || 'পাহাড়ি অর্গানিক পণ্য',
                  source: 'supabase_db_product',
                  bucket: 'products',
                  path: `product-stock/${prod.id}_main.jpg`,
                  folder: folderName,
                  folderType,
                  merchantId: sId || undefined,
                  sellerName,
                  dbProductId: prod.id,
                  productCode: prod.code,
                  productName: prod.name_bn,
                  category: prod.category,
                  createdAt: prod.created_at || new Date().toISOString()
                });
              }

              const gallery = Array.isArray(prod.gallery_urls) ? prod.gallery_urls : (Array.isArray(prod.images) ? prod.images : []);
              gallery.forEach((imgUrl: string, gIdx: number) => {
                if (imgUrl && imgUrl.startsWith('http') && !deletedUrls.has(imgUrl) && !itemMap.has(imgUrl)) {
                  itemMap.set(imgUrl, {
                    id: `prod_gallery_${prod.id}_${gIdx}`,
                    url: imgUrl,
                    name: `${prod.name_bn || prod.name_en || 'পণ্য'} (ছবি ${gIdx + 1})`,
                    source: 'supabase_db_product',
                    bucket: 'products',
                    path: `product-stock/${prod.id}_gallery_${gIdx + 1}.jpg`,
                    folder: folderName,
                    folderType,
                    merchantId: sId || undefined,
                    sellerName,
                    dbProductId: prod.id,
                    productCode: prod.code,
                    productName: prod.name_bn,
                    category: prod.category,
                    createdAt: prod.created_at || new Date().toISOString()
                  });
                }
              });
            }
          }
        } catch {}

        // 3. Map banners table
        try {
          const { data: dbBanners } = await serverSupabase.from('banners').select('*').limit(50);
          if (dbBanners && Array.isArray(dbBanners)) {
            for (const ban of dbBanners) {
              const img = ban.image_url;
              if (img && img.startsWith('http') && !deletedUrls.has(img) && !itemMap.has(img)) {
                itemMap.set(img, {
                  id: `banner_${ban.id}`,
                  url: img,
                  name: ban.title || 'হোমপেজ ব্যানার',
                  source: 'supabase_db_banner',
                  bucket: 'banners',
                  path: `banners/${ban.id}.jpg`,
                  folder: 'banners',
                  folderType: 'banners',
                  bannerTitle: ban.title,
                  dbBannerId: ban.id,
                  placement: ban.placement,
                  createdAt: ban.created_at || new Date().toISOString()
                });
              }
            }
          }
        } catch {}

        // 4. Map pahari_products table (Daily Commodity Market - "ভোগ্যপণ্য বাজার")
        try {
          const { data: dbPahari } = await serverSupabase.from('pahari_products').select('*').limit(200);
          if (dbPahari && Array.isArray(dbPahari)) {
            for (const p of dbPahari) {
              const img = p.image_url || p.image;
              if (img && typeof img === 'string' && img.startsWith('http') && !deletedUrls.has(img) && !itemMap.has(img)) {
                itemMap.set(img, {
                  id: `pahari_${p.id}`,
                  url: img,
                  name: p.product_name || 'নিত্যপ্রয়োজনীয় ভোগ্যপণ্য',
                  source: 'supabase_db_product',
                  bucket: 'products',
                  path: `commodity-market/${p.id}.jpg`,
                  folder: 'commodity-market',
                  folderType: 'commodity_market',
                  dbProductId: p.id,
                  productName: p.product_name,
                  category: p.category || 'ভোগ্যপণ্য বাজার',
                  createdAt: p.created_at || new Date().toISOString()
                });
              }
            }
          }
        } catch {}
      }

      items = Array.from(itemMap.values());
      res.json({ 
        success: true, 
        items,
        merchants: registeredSellers
      });
    } catch (err: any) {
      res.json({ success: true, items: [], merchants: [] });
    }
  });

  // Direct Permanent Media Deletion Endpoint
  // Direct Permanent Media Deletion Endpoint
  const handleMediaDelete = async (req: express.Request, res: express.Response) => {
    try {
      const {
        id,
        url,
        path: storagePath,
        candidatePaths: incomingCandidates,
        bucket: reqBucket = 'products',
        dbProductId,
        dbBannerId
      } = req.body || {};

      if (!url && !storagePath && !id) {
        return res.status(400).json({ success: false, message: 'ছবি চিহ্নিত করার তথ্য (URL/Path) প্রয়োজন' });
      }

      // 1. Resolve accurate bucket and exact object path inside that bucket
      let bucket = (reqBucket && reqBucket !== 'all' ? String(reqBucket) : '').trim();
      let exactPath = '';
      const orderedPaths: string[] = [];
      const addPath = (p?: string) => {
        if (!p || typeof p !== 'string') return;
        const clean = p.split('?')[0].split('#')[0].replace(/^\/+/, '').trim();
        if (clean && clean !== bucket && !orderedPaths.includes(clean)) {
          orderedPaths.push(clean);
        }
      };

      const isSupabaseStorageUrl = Boolean(url && typeof url === 'string' && url.includes('/storage/v1/'));

      if (url && typeof url === 'string') {
        try {
          const urlObj = new URL(url, 'http://localhost');
          const pathname = decodeURIComponent(urlObj.pathname);
          const storageRegex = /(?:storage\/v1\/(?:object\/(?:public|sign|authenticated)|render\/image\/public))\/(?<matchedBucket>[^/]+)\/(?<matchedPath>.+)$/i;
          const match = pathname.match(storageRegex);

          if (match && match.groups) {
            bucket = match.groups.matchedBucket.trim();
            exactPath = match.groups.matchedPath.split('?')[0].split('#')[0].replace(/^\/+/, '').trim();
            addPath(exactPath);
          }
        } catch {}
      }

      if (storagePath && typeof storagePath === 'string') {
        let sp = storagePath;
        try {
          sp = decodeURIComponent(storagePath);
        } catch {}
        sp = sp.split('?')[0].split('#')[0].replace(/^\/+/, '').trim();
        if (!exactPath && sp) {
          exactPath = sp;
        }
        addPath(sp);
      }

      if (Array.isArray(incomingCandidates)) {
        incomingCandidates.forEach((p: any) => {
          if (typeof p === 'string') addPath(p);
        });
      }

      if (!bucket || bucket === 'all') {
        bucket = 'products';
      }

      // Add stripped variant ONLY as secondary candidate after exactPath
      if (exactPath && exactPath.startsWith(`${bucket}/`)) {
        addPath(exactPath.slice(bucket.length + 1));
      }

      // 2. Delete file from Supabase Storage bucket using official supabase.storage.from(bucket).remove([filePath])
      let verifiedDeletedFromBucket = false;
      let lastStorageError = '';
      const removedPathsList: string[] = [];

      if (serverSupabase && orderedPaths.length > 0) {
        const primaryTargetPath = exactPath || orderedPaths[0];
        const bucketsToTry = Array.from(new Set([bucket, 'products'].filter(Boolean)));

        for (const bName of bucketsToTry) {
          try {
            // Try exact path first
            const { data: remData, error: remErr } = await serverSupabase.storage
              .from(bName)
              .remove([primaryTargetPath]);

            if (remErr) {
              console.error(`[Server Media Delete] supabase.storage.from('${bName}').remove(['${primaryTargetPath}']) error:`, remErr);
              if (!lastStorageError) {
                lastStorageError = remErr.message || String(remErr);
              }
            } else if (Array.isArray(remData) && remData.length > 0) {
              verifiedDeletedFromBucket = true;
              removedPathsList.push(`${bName}/${primaryTargetPath}`);
              break;
            }

            // Try remaining candidates if exact path returned [] without error
            const extraCandidates = orderedPaths.filter(p => p !== primaryTargetPath);
            if (!verifiedDeletedFromBucket && !remErr && extraCandidates.length > 0) {
              const { data: batchRemData, error: batchRemErr } = await serverSupabase.storage
                .from(bName)
                .remove(extraCandidates);
              if (batchRemErr) {
                console.error(`[Server Media Delete] batch remove error on '${bName}':`, batchRemErr);
                if (!lastStorageError) {
                  lastStorageError = batchRemErr.message || String(batchRemErr);
                }
              } else if (Array.isArray(batchRemData) && batchRemData.length > 0) {
                verifiedDeletedFromBucket = true;
                batchRemData.forEach((d: any) => {
                  if (d?.name) removedPathsList.push(`${bName}/${d.name}`);
                });
                break;
              }
            }
          } catch (storageErr: any) {
            console.error(`[Server Media Delete] Exception on '${bName}':`, storageErr?.message || storageErr);
            if (!lastStorageError) {
              lastStorageError = storageErr?.message || 'Storage remove exception';
            }
          }
        }

        // Verify via bucket .list() on the EXACT parent folder (never strip folder matching bucket name!)
        if (primaryTargetPath) {
          try {
            const slashIdx = primaryTargetPath.lastIndexOf('/');
            const exactFolderDir = slashIdx >= 0 ? primaryTargetPath.slice(0, slashIdx) : '';
            const exactBaseFileName = slashIdx >= 0 ? primaryTargetPath.slice(slashIdx + 1) : primaryTargetPath;

            if (exactBaseFileName) {
              const { data: checkFiles, error: checkErr } = await serverSupabase.storage
                .from(bucket)
                .list(exactFolderDir, { limit: 100, search: exactBaseFileName });

              if (!checkErr && Array.isArray(checkFiles)) {
                const stillExists = checkFiles.some((f: any) => f.name === exactBaseFileName);
                if (stillExists) {
                  verifiedDeletedFromBucket = false;
                } else if (!lastStorageError) {
                  verifiedDeletedFromBucket = true;
                }
              }
            }
          } catch (_) {}
        }
      }

      // 3. Remove local backup file if present
      let localFileRemoved = false;
      try {
        const filenamesToCheck = new Set<string>();
        orderedPaths.forEach(p => filenamesToCheck.add(path.basename(p)));
        if (url) {
          try {
            filenamesToCheck.add(path.basename(new URL(url, 'http://localhost').pathname));
          } catch {}
        }
        for (const fname of filenamesToCheck) {
          if (!fname) continue;
          const localPath = path.join(process.cwd(), 'public', 'assets', 'uploads', fname);
          if (fs.existsSync(localPath)) {
            fs.unlinkSync(localPath);
            localFileRemoved = true;
            console.log(`[Server] Removed local backup file: ${localPath}`);
          }
        }
      } catch (err: any) {
        console.warn('[Server] Error removing local backup file:', err?.message);
      }

      const deletionConfirmed =
        verifiedDeletedFromBucket ||
        localFileRemoved ||
        (!isSupabaseStorageUrl && Boolean(url));

      if (!deletionConfirmed) {
        return res.status(400).json({
          success: false,
          verifiedDeleted: false,
          bucket,
          path: exactPath || orderedPaths[0] || '',
          error:
            lastStorageError ||
            `সুপাবেস '${bucket}' বাকেটে RLS পলিসি বা ট্রিগারের কারণে ফাইলটি ডিলিট করা যায়নি।`
        });
      }

      // 4. ONLY AFTER confirmed deletion: record deleted URL & clean DB / JSON references
      if (url) {
        recordDeletedMediaUrl(url);
      }

      if (serverSupabase) {
        for (const metaTable of ['media_library', 'media_gallery']) {
          try {
            if (url) {
              await serverSupabase.from(metaTable).delete().eq('url', url);
              await serverSupabase.from(metaTable).delete().eq('public_url', url);
            }
            for (const cp of orderedPaths) {
              await serverSupabase.from(metaTable).delete().eq('file_path', cp);
              await serverSupabase.from(metaTable).delete().eq('storage_path', cp);
            }
          } catch (_) {}
        }
      }

      if (serverSupabase && url) {
        try {
          await serverSupabase.from('products').update({ image_url: '', updated_at: new Date().toISOString() }).eq('image_url', url);
          if (dbProductId) {
            await serverSupabase.from('products').update({ image_url: '', updated_at: new Date().toISOString() }).eq('id', dbProductId);
          }
        } catch {}

        try {
          await serverSupabase.from('merchant_products').update({ image_url: '', updated_at: new Date().toISOString() }).eq('image_url', url);
          if (dbProductId) {
            await serverSupabase.from('merchant_products').update({ image_url: '', updated_at: new Date().toISOString() }).eq('id', dbProductId);
          }
        } catch {}

        try {
          await serverSupabase.from('banners').update({ image_url: '', updated_at: new Date().toISOString() }).eq('image_url', url);
          if (dbBannerId) {
            await serverSupabase.from('banners').update({ image_url: '', updated_at: new Date().toISOString() }).eq('id', dbBannerId);
          }
          await serverSupabase.from('platform_banners').update({ image_url: '', updated_at: new Date().toISOString() }).eq('image_url', url);
        } catch {}

        try {
          await serverSupabase.from('bhogya_pannya_bazar').update({ image_url: '' }).eq('image_url', url);
          await serverSupabase.from('pahari_products').update({ image_url: '' }).eq('image_url', url);
          if (dbProductId) {
            await serverSupabase.from('pahari_products').update({ image_url: '' }).eq('id', dbProductId);
          }
        } catch {}

        try {
          await serverSupabase.from('product_sellers').update({ logo_url: '' }).eq('logo_url', url);
          await serverSupabase.from('product_sellers').update({ banner_url: '' }).eq('banner_url', url);
        } catch {}

        try {
          await serverSupabase.from('service_providers').update({ photo_url: '' }).eq('photo_url', url);
        } catch {}
      }

      try {
        const jsonFiles = ['products.json', 'merchant_products.json', 'banners.json', 'pahari_products.json', 'second_hand_products.json'];
        for (const file of jsonFiles) {
          const filePath = path.join(DATA_DIR, file);
          if (fs.existsSync(filePath)) {
            let content = fs.readFileSync(filePath, 'utf-8');
            if (url && content.includes(url)) {
              content = content.split(JSON.stringify(url)).join('""');
              fs.writeFileSync(filePath, content, 'utf-8');
            }
          }
        }
      } catch (err: any) {
        console.warn('[Server] Error cleaning local JSON files:', err?.message);
      }

      return res.json({
        success: true,
        verifiedDeleted: true,
        removedPaths: removedPathsList,
        message: 'ছবিটি সুপাবেস স্টোরেজ বাকেট ও ডাটাবেজ থেকে স্থায়ীভাবে মুছে ফেলা হয়েছে।'
      });
    } catch (err: any) {
      console.error('[Server] Failed to delete media item:', err);
      return res.status(500).json({ success: false, error: err?.message || 'ছবি মুছতে ব্যর্থ হয়েছে' });
    }
  };

