      usageInstructions: d.usage_and_storage || d.usage_instructions || d.usageInstructions || '',
      origin: d.origin || d.production_origin || d.productionOrigin || 'পার্বত্য চট্টগ্রাম',
      productionOrigin: d.production_origin || d.productionOrigin || d.origin || '',
      quality_standard: d.quality_standard || d.quality_standards || d.qualityStandards || '১০০% বিশুদ্ধ ও পরীক্ষিত',
      seller_info: d.store_name || d.storeName || d.shop_name || d.shopName || d.business_name || d.businessName || d.seller_info || d.seller_name || d.sellerName || 'ঝাদিমাদি ভেরিফাইড মার্চেন্ট নেটওয়ার্ক',
      sellerName: d.store_name || d.storeName || d.shop_name || d.shopName || d.business_name || d.businessName || d.seller_info || d.seller_name || d.sellerName || 'ঝাদিমাদি ভেরিফাইড মার্চেন্ট নেটওয়ার্ক',
      seller_name: d.store_name || d.storeName || d.shop_name || d.shopName || d.business_name || d.businessName || d.seller_info || d.seller_name || d.sellerName || 'ঝাদিমাদি ভেরিফাইড মার্চেন্ট নেটওয়ার্ক',
      storeName: d.store_name || d.storeName || d.shop_name || d.shopName || d.business_name || d.businessName || undefined,
