  const FORM_CATEGORIES_FILE = path.join(DATA_DIR, 'form_categories.json');

  const readLocalFormCategories = () => {
    try {
      if (fs.existsSync(FORM_CATEGORIES_FILE)) {
        const raw = fs.readFileSync(FORM_CATEGORIES_FILE, 'utf-8');
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return parsed;
      }
    } catch (_) {}
    return [];
  };

  const writeLocalFormCategories = (list: any[]) => {
    try {
      if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
      fs.writeFileSync(FORM_CATEGORIES_FILE, JSON.stringify(list, null, 2), 'utf-8');
    } catch (_) {}
  };

