  app.get('/api/form-categories', async (req, res) => {
    try {
      const formType = String(req.query.form_type || req.query.type || '').trim().toLowerCase();
      let categories: any[] = [];
      let loadedFromDb = false;

      if (serverSupabase) {
        try {
          let query = serverSupabase
            .from('form_categories')
            .select('*')
            .order('created_at', { ascending: true });
          
          if (formType) {
            query = query.eq('form_type', formType);
          }

          const { data, error } = await query;
          if (!error && Array.isArray(data) && data.length > 0) {
            categories = data;
            loadedFromDb = true;
          }
        } catch (_) {}
      }

      if (!loadedFromDb) {
        const localList = readLocalFormCategories();
        if (formType) {
          categories = localList.filter((item: any) => String(item.form_type).toLowerCase() === formType);
        } else {
          categories = localList;
        }
      }

      res.json({
        success: true,
        count: categories.length,
        categories
      });
    } catch (err: any) {
      res.status(500).json({ success: false, message: err?.message || 'Failed to load form categories' });
    }
  });

