  app.post('/api/form-categories', requireAdminAuth, async (req, res) => {
    try {
      const { form_type, category_name } = req.body || {};
      const cleanType = String(form_type || '').trim().toLowerCase();
      const cleanName = String(category_name || '').trim();

      if (!cleanType || !['merchant', 'stock', 'bhogyoponno'].includes(cleanType)) {
        return res.status(400).json({ success: false, message: 'সঠিক ফর্ম টাইপ (merchant, stock, bhogyoponno) প্রদান করুন' });
      }

      if (!cleanName) {
        return res.status(400).json({ success: false, message: 'ক্যাটাগরির নাম প্রদান আবশ্যক' });
      }

      const newId = `cat-${cleanType[0]}-${Date.now().toString(36)}-${Math.random().toString(36).substring(2, 6)}`;
      const newCategory = {
        id: newId,
        form_type: cleanType,
        category_name: cleanName,
        created_at: new Date().toISOString()
      };

      // 1. Save to Supabase form_categories table
      if (serverSupabase) {
        try {
          const { data, error } = await serverSupabase
            .from('form_categories')
            .insert([{
              form_type: cleanType,
              category_name: cleanName
            }])
            .select()
            .single();

          if (!error && data) {
            newCategory.id = data.id || newCategory.id;
            newCategory.created_at = data.created_at || newCategory.created_at;
          }
        } catch (_) {}
      }

      // 2. Save to local fallback file
      const localList = readLocalFormCategories();
      const exists = localList.some((item: any) => 
        String(item.form_type).toLowerCase() === cleanType && 
        String(item.category_name).trim().toLowerCase() === cleanName.toLowerCase()
      );
      if (!exists) {
        localList.push(newCategory);
        writeLocalFormCategories(localList);
      }

      res.json({
        success: true,
        category: newCategory,
        message: 'ক্যাটাগরি সফলভাবে যুক্ত করা হয়েছে'
      });
    } catch (err: any) {
      res.status(500).json({ success: false, message: err?.message || 'Failed to add form category' });
    }
  });

