  // GET /api/service-providers/:id/dashboard-overview: Real-time Stats, Leads, Inquiries & Notifications
  app.get('/api/service-providers/:id/dashboard-overview', (req, res) => {
    const { id } = req.params;
    const cleanPid = String(id || '').toLowerCase().trim();

    const providerBookings = liveBookings.filter(b => 
      String(b.workerId).toLowerCase() === cleanPid ||
      String(b.provider?.id).toLowerCase() === cleanPid ||
      String(b.workerPhone) === String(id)
    );

    const pendingCount = providerBookings.filter(b => b.status !== 'Completed' && b.status !== 'completed').length;
    const completedCount = providerBookings.filter(b => b.status === 'Completed' || b.status === 'completed').length;

    const inquiries = liveProviderInquiries.filter(i => 
      String(i.providerId).toLowerCase() === cleanPid
    );

    // Retrieve leads for this provider
    // Open leads: visible to all providers in area (phone & address masked)
    // Claimed leads: visible ONLY to the provider who claimed it (fully unmasked)
    const providerLeads = liveServiceRequests
      .filter(l => l.status === 'open' || (String(l.claimedByProviderId || '').toLowerCase().trim() === cleanPid))
      .map(lead => {
        const isClaimedByMe = String(lead.claimedByProviderId || '').toLowerCase().trim() === cleanPid;
        if (isClaimedByMe) {
          return {
            ...lead,
            isLockedByMe: true,
            phoneMasked: false
          };
        }
        return {
          ...lead,
          customerPhone: '০১৮******XX',
          streetAddress: '🔒 লক করা (কাজ গ্রহণ করলে উন্মুক্ত হবে)',
          isLockedByMe: false,
          phoneMasked: true
        };
      });

    // Check if there are notifications for this provider or broadcast notifications
    const notifications = liveProviderNotifications.filter(n => 
      String(n.providerId).toLowerCase() === cleanPid ||
      n.providerId === 'sp_broadcast'
    );

    const unreadNotificationsCount = notifications.filter(n => !n.read).length;

    return res.json({
      success: true,
      stats: {
        totalRequests: providerBookings.length + providerLeads.length,
        pendingCount,
        completedCount,
        leadsCount: providerLeads.length,
        inquiriesCount: inquiries.length,
        unreadNotificationsCount
      },
      bookings: providerBookings,
      leads: providerLeads,
      inquiries,
      notifications
    });
  });

