  // 2. LIVE AUTH ENDPOINTS
  app.post('/api/auth/check-unique', async (req, res) => {
    const { phone, email } = req.body;
    const cleanPhone = (phone || '').replace(/[^0-9]/g, '');
    const cleanEmail = (email || '').trim().toLowerCase();
    const isSyntheticEmail = !cleanEmail || cleanEmail.endsWith('@jhadimadi.com') || cleanEmail.includes('placeholder');

    const DUPLICATE_MSG = 'এই ফোন নম্বর অথবা ইমেইল দিয়ে ইতিমধ্যে একটি অ্যাকাউন্ট তৈরি করা হয়েছে।';

    // 1. Check in-memory liveUsers
    const allUsers = Object.values(liveUsers) as any[];
    for (const u of allUsers) {
      if (cleanPhone && cleanPhone.length >= 10 && u.phone) {
        const uPhoneDigits = u.phone.replace(/[^0-9]/g, '');
        if (uPhoneDigits === cleanPhone || (cleanPhone.endsWith(uPhoneDigits) && uPhoneDigits.length >= 10)) {
          return res.json({ isAvailable: false, conflictField: 'phone', message: DUPLICATE_MSG });
        }
      }
      if (cleanEmail && !isSyntheticEmail && u.email) {
        if (u.email.trim().toLowerCase() === cleanEmail) {
          return res.json({ isAvailable: false, conflictField: 'email', message: DUPLICATE_MSG });
        }
      }
    }

    // 2. Check Supabase profiles table
    if (serverSupabase) {
      try {
        if (cleanPhone && cleanPhone.length >= 10) {
          const phoneVariants = [
            cleanPhone,
            `+88${cleanPhone}`,
            `88${cleanPhone}`,
            cleanPhone.startsWith('88') ? cleanPhone.slice(2) : null,
            cleanPhone.startsWith('+88') ? cleanPhone.slice(3) : null
          ].filter(Boolean) as string[];

          const { data: phoneMatches } = await serverSupabase
            .from('profiles')
            .select('id, phone')
            .in('phone', phoneVariants)
            .limit(1);

          if (phoneMatches && phoneMatches.length > 0) {
            return res.json({ isAvailable: false, conflictField: 'phone', message: DUPLICATE_MSG });
          }
        }

        if (cleanEmail && !isSyntheticEmail) {
          const { data: emailMatches } = await serverSupabase
            .from('profiles')
            .select('id, email')
            .ilike('email', cleanEmail)
            .limit(1);

          if (emailMatches && emailMatches.length > 0) {
            return res.json({ isAvailable: false, conflictField: 'email', message: DUPLICATE_MSG });
          }
        }
      } catch (err: any) {
        console.warn('[Server] check-unique Supabase notice:', err?.message || err);
      }
    }

    return res.json({ isAvailable: true });
  });

  app.post('/api/auth/register', strictLimiter('auth-register', 10, 15 * 60 * 1000), async (req, res) => {
    const { name, phone, email, password, division, district, upazila, mahalla, nidFrontUrl, nidBackUrl, selfieUrl } = req.body;
    if ((!phone && !email) || !name) {
      return res.status(400).json({ success: false, message: 'মোবাইল নম্বর অথবা ইমেইল এবং নাম আবশ্যক।' });
    }

    const cleanPhone = (phone || '').replace(/[^0-9]/g, '');
    const cleanEmail = (email || '').trim().toLowerCase();
    const isSyntheticEmail = !cleanEmail || cleanEmail.endsWith('@jhadimadi.com') || cleanEmail.includes('placeholder');
    const DUPLICATE_MSG = 'এই ফোন নম্বর অথবা ইমেইল দিয়ে ইতিমধ্যে একটি অ্যাকাউন্ট তৈরি করা হয়েছে।';

    if (!password) {
      return res.status(400).json({ success: false, message: 'পাসওয়ার্ড প্রদান করা আবশ্যক।' });
    }

    // Uniqueness validation against in-memory liveUsers
    const allUsers = Object.values(liveUsers) as any[];
    for (const u of allUsers) {
      if (cleanPhone && cleanPhone.length >= 10 && u.phone) {
        const uPhoneDigits = u.phone.replace(/[^0-9]/g, '');
        if (uPhoneDigits === cleanPhone || (cleanPhone.endsWith(uPhoneDigits) && uPhoneDigits.length >= 10)) {
          return res.status(400).json({ success: false, code: '23505', message: DUPLICATE_MSG });
        }
      }
      if (cleanEmail && !isSyntheticEmail && u.email) {
        if (u.email.trim().toLowerCase() === cleanEmail) {
          return res.status(400).json({ success: false, code: '23505', message: DUPLICATE_MSG });
        }
      }
    }

    // Uniqueness validation against Supabase profiles table
    if (serverSupabase) {
      try {
        if (cleanPhone && cleanPhone.length >= 10) {
          const phoneVariants = [
            cleanPhone,
            `+88${cleanPhone}`,
            `88${cleanPhone}`,
            cleanPhone.startsWith('88') ? cleanPhone.slice(2) : null,
            cleanPhone.startsWith('+88') ? cleanPhone.slice(3) : null
          ].filter(Boolean) as string[];

          const { data: phoneMatches } = await serverSupabase
            .from('profiles')
            .select('id, phone')
            .in('phone', phoneVariants)
            .limit(1);

          if (phoneMatches && phoneMatches.length > 0) {
            return res.status(400).json({ success: false, code: '23505', message: DUPLICATE_MSG });
          }
        }

        if (cleanEmail && !isSyntheticEmail) {
          const { data: emailMatches } = await serverSupabase
            .from('profiles')
            .select('id, email')
            .ilike('email', cleanEmail)
            .limit(1);

          if (emailMatches && emailMatches.length > 0) {
            return res.status(400).json({ success: false, code: '23505', message: DUPLICATE_MSG });
          }
        }
      } catch (err: any) {
        console.warn('[Server] Supabase uniqueness check notice:', err?.message || err);
      }
    }

    // Hash password securely with salted scrypt
    const hashedPassword = hashPassword(password);

    // Standardized Customer ID Generation: [Prefix] - [Area Postal Code] - [Sequential Number]
    // Strictly formatted as: CM-[PostalCode]-[001, 002, 003...] (e.g., CM-3540-001)
    const userRole = req.body.role || 'customer';
    const rawPostalCode = req.body.postalCode || req.body.postCode || req.body.postal_code || req.body.post_code || '';
    let assignedCustomerId = '';
    let sequentialStats: any = null;
    const isCustomerOrMember = userRole === 'customer' || userRole === 'buyer' || userRole === 'member' || !req.body.role;

    if (isCustomerOrMember || req.body.customerId) {
      try {
        sequentialStats = await fetchHighestSerialAndCustomersForPostalCode(rawPostalCode, {
          district: district || req.body.district,
          upazila: upazila || req.body.upazila || req.body.thana,
          thana: req.body.thana,
          address: mahalla || req.body.address || req.body.mahalla,
          mahalla: mahalla || req.body.mahalla,
          division: division || req.body.division,
          existingPhone: cleanPhone || phone
        });

        const pCode = sequentialStats.postalCode || '4400';
        const clientCandidate = req.body.customerId ? String(req.body.customerId).trim().toUpperCase() : '';
        const isValidCmPattern = clientCandidate && new RegExp(`^CM[\\-_/]${pCode}[\\-_/](\\d+)$`, 'i').test(clientCandidate);

        if (isValidCmPattern) {
          const clientMatch = clientCandidate.match(new RegExp(`^CM[\\-_/]${pCode}[\\-_/](\\d+)$`, 'i'));
          const clientSerial = clientMatch ? parseInt(clientMatch[1], 10) : 0;
          const isSerialAlreadyUsed = clientSerial > 0 && sequentialStats.usedSerials?.includes(clientSerial);

          if (!isSerialAlreadyUsed && clientSerial > 0) {
            assignedCustomerId = `CM-${pCode}-${String(clientSerial).padStart(3, '0')}`;
          } else {
            // Serial collision detected in database; assign authoritative next sequential ID
            assignedCustomerId = sequentialStats.customerId;
          }
        } else {
          assignedCustomerId = sequentialStats.customerId;
        }
      } catch (genErr) {
        console.warn('[Server] Customer ID generation warning, using fallback:', genErr);
        const pCode = getPostalCodeForAddress({
          postalCode: rawPostalCode,
          district,
          upazila,
          address: mahalla,
          division
        }) || '4400';
        assignedCustomerId = `CM-${pCode}-001`;
      }
    }

    const resolvedPostal = sequentialStats?.postalCode || getPostalCodeForAddress({
      postalCode: rawPostalCode,
      district,
      upazila,
      address: mahalla,
      division
    });

    const newUser: any = {
      id: assignedCustomerId || ('u_' + Date.now()),
      customerId: assignedCustomerId || undefined,
      customer_id: assignedCustomerId || undefined,
      unique_id: assignedCustomerId || undefined,
      uniqueId: assignedCustomerId || undefined,
      memberUID: assignedCustomerId || undefined,
      memberId: assignedCustomerId || undefined,
      name,
      phone: phone || '',
      email: email || '',
      password: hashedPassword,
      role: userRole,
      postalCode: resolvedPostal,
      division: division || 'Chittagong Division (চট্টগ্রাম)',
      district: district || 'Rangamati',
      upazila: upazila || 'Rangamati Sadar',
      mahalla: mahalla || 'বনরুপা (Bonorupa)',
      avatar: selfieUrl || 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80',
      nidFrontUrl,
      nidBackUrl,
      selfieUrl,
      isNidVerified: true,
      isPaidMember: true,
      createdAt: new Date().toISOString().split('T')[0],
    };

    const identifier = (phone || email || '').trim().toLowerCase();
    liveUsers[identifier] = newUser;
    if (phone) liveUsers[phone] = newUser;
    if (cleanPhone) liveUsers[cleanPhone] = newUser;
    if (email) liveUsers[email.toLowerCase()] = newUser;
    if (assignedCustomerId) {
      liveUsers[assignedCustomerId] = newUser;
      liveUsers[assignedCustomerId.toLowerCase()] = newUser;
    }

    // Synchronize user profile directly to Supabase profiles table with 23505 error handling
    try {
      if (serverSupabase) {
        const { error: profileError } = await serverSupabase.from('profiles').upsert([{
          id: newUser.id,
          full_name: newUser.name,
          phone: newUser.phone,
          email: newUser.email,
          role: newUser.role,
          division: newUser.division,
          district: newUser.district,
          upazila: newUser.upazila,
          address: `${newUser.mahalla}, ${newUser.upazila}`,
          postal_code: resolvedPostal,
          unique_id: assignedCustomerId || newUser.id,
          customer_id: assignedCustomerId || undefined,
          blood_group: req.body.bloodGroup || '',
          avatar_url: newUser.avatar,
          is_nid_verified: true,
          updated_at: new Date().toISOString()
        }], { onConflict: 'id' });

        if (profileError) {
          const isConstraint = 
            profileError.code === '23505' || 
            profileError.message?.includes('23505') || 
            profileError.message?.toLowerCase().includes('duplicate') ||
            profileError.message?.toLowerCase().includes('unique');

          if (isConstraint) {
            delete liveUsers[identifier];
            if (phone) delete liveUsers[phone];
            if (cleanPhone) delete liveUsers[cleanPhone];
            if (email) delete liveUsers[email.toLowerCase()];
            if (assignedCustomerId) {
              delete liveUsers[assignedCustomerId];
              delete liveUsers[assignedCustomerId.toLowerCase()];
            }
            return res.status(400).json({ success: false, code: '23505', message: DUPLICATE_MSG });
          }
          console.warn('[Server] Supabase profile upsert warning:', profileError);
        }
      }
    } catch (e: any) {
      const isConstraint = 
        e?.code === '23505' || 
        e?.message?.includes('23505') || 
        e?.message?.toLowerCase().includes('duplicate key');

      if (isConstraint) {
        delete liveUsers[identifier];
        if (phone) delete liveUsers[phone];
        if (cleanPhone) delete liveUsers[cleanPhone];
        if (email) delete liveUsers[email.toLowerCase()];
        if (assignedCustomerId) {
          delete liveUsers[assignedCustomerId];
          delete liveUsers[assignedCustomerId.toLowerCase()];
        }
        return res.status(400).json({ success: false, code: '23505', message: DUPLICATE_MSG });
      }
      console.warn('[Server] Error persisting user to Supabase profiles:', e);
    }

    // Persist new registration to registered_members.json for persistent records
    try {
      const membersPath = path.join(DATA_DIR, 'registered_members.json');
      if (fs.existsSync(membersPath)) {
        const raw = fs.readFileSync(membersPath, 'utf-8');
        const members = JSON.parse(raw);
        if (Array.isArray(members)) {
          const existingIdx = members.findIndex(m => 
            (cleanPhone && m.phone && m.phone.replace(/[^0-9]/g, '') === cleanPhone) ||
            (cleanEmail && !isSyntheticEmail && m.email && m.email.toLowerCase() === cleanEmail) ||
            (assignedCustomerId && (m.id === assignedCustomerId || m.customerId === assignedCustomerId || m.unique_id === assignedCustomerId))
          );
          const memberEntry = {
            id: newUser.id,
            customerId: assignedCustomerId || undefined,
            customer_id: assignedCustomerId || undefined,
            unique_id: assignedCustomerId || newUser.id,
            name: newUser.name,
            phone: newUser.phone,
            email: newUser.email,
            role: newUser.role,
            division: newUser.division,
            district: newUser.district,
            upazila: newUser.upazila,
            postalCode: resolvedPostal,
            createdAt: newUser.createdAt
          };
          if (existingIdx >= 0) {
            members[existingIdx] = { ...members[existingIdx], ...memberEntry };
          } else {
            members.push(memberEntry);
          }
          fs.writeFileSync(membersPath, JSON.stringify(members, null, 2), 'utf-8');
        }
      }
    } catch (fsErr) {
      console.warn('[Server] Error updating registered_members.json:', fsErr);
    }

    const { password: _p, ...safeUser } = newUser;
    res.json({
      success: true,
      user: safeUser,
      customerId: assignedCustomerId || safeUser.customerId,
      message: 'রেজিস্ট্রেশন সফল হয়েছে!'
    });
  });

